'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}), decimal=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2});
const n=v=>number.format(v), money=(v,currency='RUB')=>decimal.format(Number(v))+' '+(currency==='RUB'?'₽':currency);
const date=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'ещё нет';
const shortDate=v=>new Date(v+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
let stores=[],snapshots=new Map(),versions=new Map(),failures=new Map(),rows=[],filtered=[],page=1,busy=false,pendingRefresh=false;
const size=50;
async function api(url,body){const response=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const value=await response.json();if(!response.ok)throw Error(value.error||'Не удалось загрузить данные');return value}
function selectedStores(){return stores.filter(s=>(!$('store').value||s.id===$('store').value)&&(!$('market').value||(s.id.startsWith('wb-')?'WB':'Ozon')===$('market').value))}
function filters(){return {store:$('store').value,market:$('market').value,query:$('search').value,issue:$('issue').value,sort:$('sort').value,hideInactive:$('hide-inactive').checked}}
function buildStoreSelect(){const old=$('store').value,market=$('market').value;$('store').innerHTML='<option value="">Все магазины</option>'+stores.filter(s=>!market||(s.id.startsWith('wb-')?'WB':'Ozon')===market).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if([...$('store').options].some(o=>o.value===old))$('store').value=old}
async function refresh(force=false){
 if(busy){pendingRefresh=true;return}busy=true;$('refresh-view').disabled=true;
 try{stores=await api('/api/stores');buildStoreSelect();const need=stores.filter(s=>force||!snapshots.has(s.id)||versions.get(s.id)!==(s.revision||s.updatedAt));
  const results=await Promise.allSettled(need.map(async s=>{const d=await api('/api/data?id='+encodeURIComponent(s.id));snapshots.set(s.id,d);versions.set(s.id,s.revision||s.updatedAt);failures.delete(s.id)}));
  results.forEach((r,i)=>{if(r.status==='rejected')failures.set(need[i].id,r.reason.message)});
  const failed=stores.filter(s=>failures.has(s.id));$('notice').className=failed.length?'error':'';$('notice').textContent=failed.length?'Не удалось обновить: '+failed.map(s=>s.name).join(', ')+'. Показаны последние доступные снимки.':'';
  rows=PultModel.rowsFor(stores,snapshots);render();
 }catch(e){$('notice').className='error';$('notice').textContent=e.message+' · Обновите страницу, если сервер перезапускался.'}
 finally{busy=false;$('refresh-view').disabled=false;if(pendingRefresh){pendingRefresh=false;void refresh()}}
}
function scopeRows(){const ids=new Set(selectedStores().map(s=>s.id));return rows.filter(p=>ids.has(p.storeId)&&(!$('hide-inactive').checked||!PultModel.isInactive(p)))}
function render(){
 const scope=selectedStores(),list=scopeRows(),loaded=scope.map(s=>snapshots.get(s.id)).filter(Boolean),ozonRows=list.filter(p=>p.market==='Ozon');
 const filled=ozonRows.filter(p=>p.cost?.status==='filled').length,missing=ozonRows.length-filled;
 const ozon=loaded.filter(d=>d.market!=='WB'),complete=ozon.every(d=>d.sections.finance?.ok),amount=ozon.reduce((sum,d)=>sum+d.operations.filter(o=>!o.currency||o.currency==='RUB').reduce((s,o)=>s+Math.round(o.amount*100),0),0)/100;
 const scopedIds=new Set(scope.map(s=>s.id)),hidden=rows.filter(p=>scopedIds.has(p.storeId)&&PultModel.isInactive(p)).length;$('visibility-count').textContent=($('hide-inactive').checked?'Скрыто: '+n(hidden):'В полном списке непродающихся: '+n(hidden))+'. Статусы «Не продаётся» и архив. Готовые к продаже остаются. Статусы WB пока не загружены. Финансы включают все операции магазинов.';
 const records=loaded.reduce((s,d)=>s+d.operationCount,0),count=scope.filter(s=>snapshots.get(s.id)).length;
 $('period-note').textContent=loaded.length?`${count} из ${scope.length} магазинов · Сохранённые данные за ${[...new Set(loaded.map(d=>shortDate(d.period.from)+' — '+shortDate(d.period.to)))].join('; ')}`:'Снимков пока нет. Подключите магазин или запустите импорт.';
 const dates=loaded.map(d=>Date.parse(d.completedAt)).filter(Number.isFinite),oldest=dates.length?Math.min(...dates):null;
 $('freshness').textContent=oldest?'Самый ранний снимок: '+date(oldest)+(Date.now()-oldest>86400000?' · обновите данные':''):'Ожидаем первую загрузку';
 $('metrics').innerHTML=[
  ['Карточки товаров',n(list.length),`Магазинов в обзоре: ${count}`,''],
  ['Начислено Ozon',ozon.length?money(amount):'—',ozon.length?(complete?'За период снимков · не прибыль':'Часть финансовых данных не загружена'):'Для WB итог ещё не рассчитан',complete?'':'warn'],
  ['Себестоимость Ozon',ozonRows.length?decimal.format(filled/ozonRows.length*100)+'%':'—',ozonRows.length?`${n(filled)} заполнено · ${n(missing)} требуют проверки`:'Себестоимость WB не сопоставлена',missing?'warn':'good'],
  ['Финансовые записи',n(records),'Начисления Ozon и строки отчётов WB','']
 ].map(([label,value,note,kind])=>`<article class="metric"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value ${String(value).length>14?'compact':''}">${value}</div><div class="metric-note ${kind}">${note}</div></article>`).join('');
 const issues=[['cost','!','Себестоимость Ozon','Нулевые и незаполненные значения',missing],['zero','↓','Нулевой остаток','Проверить наличие и доступность',list.filter(p=>p.quantity===0).length],['unknown','?','Остаток неизвестен','Нет записи или раздел не загружен',list.filter(p=>p.quantity===null).length]];
 $('attention').innerHTML=issues.map(([key,icon,title,note,count])=>`<button class="attention-button" data-issue="${key}"><span class="attention-icon">${icon}</span><span><strong>${title}</strong><small>${note}</small></span><b>${n(count)}</b></button>`).join('');
 renderChart(ozon);renderTable();renderFinance(scope);renderStores(scope);
}
function renderChart(data){
 if(!data.length){$('chart').innerHTML='<div class="empty">Динамика доступна для магазинов Ozon.<br>Выберите Ozon или все площадки.</div>';return}
 const byDay=new Map();for(const d of data)for(const day of d.daily||[])if(day.currency==='RUB')byDay.set(day.date,(byDay.get(day.date)||0)+Math.round(day.amount*100));
 const points=[...byDay].sort(([a],[b])=>a.localeCompare(b)).map(([day,cents])=>({day,value:cents/100}));if(!points.length){$('chart').innerHTML='<div class="empty">Нет начислений для графика</div>';return}
 const min=Math.min(0,...points.map(p=>p.value)),max=Math.max(1,...points.map(p=>p.value)),range=max-min;
 const width=640,height=185,left=51,right=13,top=12,bottom=28,plotH=height-top-bottom,plotW=width-left-right,y=v=>top+(max-v)/range*plotH,zero=y(0),step=plotW/points.length;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Начисления Ozon по дням. Всего ${esc(money(points.reduce((s,p)=>s+p.value,0)))}">`;
 for(let i=0;i<4;i++){const v=min+range*i/3,py=y(v);svg+=`<line x1="${left}" y1="${py}" x2="${width-right}" y2="${py}" stroke="#eef2f8"/><text x="${left-8}" y="${py+3}" text-anchor="end">${decimal.format(v/1000000)}м</text>`}
 svg+=`<line x1="${left}" y1="${zero}" x2="${width-right}" y2="${zero}" stroke="#cbd7eb"/>`;
 points.forEach((p,i)=>{const x=left+step*i+step*.18,py=y(p.value),barH=Math.max(Math.abs(py-zero),.5);svg+=`<rect x="${x}" y="${Math.min(py,zero)}" width="${step*.64}" height="${barH}" rx="2" fill="${p.value<0?'#e1a26d':'#6384fa'}"><title>${shortDate(p.day)}: ${money(p.value)}</title></rect>`;if(i===0||i===points.length-1||(i%7===0&&i<points.length-4))svg+=`<text x="${x+step*.3}" y="${height-7}" text-anchor="middle">${shortDate(p.day)}</text>`});$('chart').innerHTML=svg+'</svg>';
}
function renderTable(){
 filtered=PultModel.filterRows(rows,filters());page=Math.max(1,Math.min(page,Math.ceil(filtered.length/size)||1));const view=filtered.slice((page-1)*size,page*size);
 $('product-rows').innerHTML=view.map(p=>{const state=p.market==='WB'?'Не сопоставлена':p.cost?.status==='filled'?'Себестоимость есть':'Проверить себестоимость';return `<tr><td><button class="product-title" data-product="${esc(p.key)}" title="${esc(p.name)}">${esc(p.name||'Без названия')}</button><span class="sub">${esc(p.offer_id)} · SKU ${esc(p.sku||'—')}</span>${p.salesStatus?'<span class="sub">'+esc(p.salesStatus)+'</span>':''}</td><td><span class="platform ${p.market==='WB'?'wb':''}">${p.market}</span>${esc(p.storeName.replace('WB · ',''))}</td><td class="numeric">${p.price!=null?money(p.price,p.currency_code||'RUB'):'—'}</td><td class="numeric">${p.cost?.status==='filled'?money(p.cost.unitCost,p.cost.currency):p.cost?.status==='zero'?'<span class="pill warn">0 · проверить</span>':'—'}</td><td class="numeric">${p.quantity===null?'<span class="pill muted">Неизвестен</span>':p.quantity===0?'<span class="pill warn">0</span>':n(p.quantity)}</td><td><span class="pill ${p.market==='WB'?'muted':p.cost?.status==='filled'?'':'warn'}">${state}</span></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Нет товаров по выбранным условиям. Измените поиск или сбросьте фильтры.</td></tr>';
 $('table-count').textContent=filtered.length?`${n((page-1)*size+1)}–${n(Math.min(page*size,filtered.length))} из ${n(filtered.length)} товаров`:'Найдено 0 товаров';$('page-info').textContent=page+' / '+(Math.ceil(filtered.length/size)||1);$('prev').disabled=page===1;$('next').disabled=page*size>=filtered.length;$('export').disabled=!filtered.length;
}
function renderFinance(scope){$('finance-rows').innerHTML=scope.map(s=>{const d=snapshots.get(s.id);if(!d)return `<tr><td>${esc(s.name)}</td><td colspan="4">Ожидаем импорт</td></tr>`;const sums={};for(const o of d.operations)sums[o.currency||'RUB']=(sums[o.currency||'RUB']||0)+Math.round(o.amount*100);const value=d.financeAmountKnown===false?'Итог не рассчитан':Object.entries(sums).map(([c,v])=>money(v/100,c)).join(' / ')||money(0);return `<tr><td>${esc(s.name)}</td><td>${shortDate(d.period.from)} — ${shortDate(d.period.to)}</td><td class="numeric">${n(d.operationCount)}</td><td class="numeric">${esc(value)}</td><td><span class="pill ${d.sections.finance?.ok?'':'warn'}">${d.sections.finance?.ok?'Импорт завершён':'Загружено частично'}</span></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Нет подключённых магазинов</td></tr>'}
function renderStores(scope){$('store-cards').innerHTML=scope.map(s=>{const d=snapshots.get(s.id),running=s.job?.status==='running',errors=[...(s.job?.errors||[]),...Object.values(d?.sections||{}).filter(x=>x.ok===false).map(x=>x.error)].filter(Boolean),kind=running?'muted':errors.length?'warn':d?'':'muted',status=running?'Идёт импорт':errors.length?'Требует проверки':d?'Данные загружены':'Ожидает импорта';return `<article class="store-card"><span class="pill ${kind}">${status}</span><h3>${esc(s.name)}</h3><p>Последний снимок: ${date(d?.completedAt)}</p><div class="store-stats"><div><strong>${d?n(d.products.length):'—'}</strong><span>карточек</span></div><div><strong>${d?n(d.operationCount):'—'}</strong><span>финансовых записей</span></div></div><p>${running?esc(s.job.stage)+' · '+n(s.job.count)+' записей':errors.length?esc([...new Set(errors)].join('; ')):'Доступ только для чтения'}</p><button class="button secondary" data-sync="${esc(s.id)}" ${running?'disabled':''}>${running?'Импорт выполняется…':'↻ Обновить из '+(s.id.startsWith('wb-')?'WB':'Ozon')}</button></article>`}).join('')}
function openDetail(key){const p=rows.find(r=>r.key===key);if(!p)return;const cost=p.cost?.status==='filled'?money(p.cost.unitCost,p.cost.currency):p.cost?.status==='zero'?'0 · проверить':'Не загружена';$('detail-content').innerHTML=`<h2 class="detail-title">${esc(p.name)}</h2><p>${esc(p.storeName)} · ${esc(p.offer_id)} · SKU ${esc(p.sku||'—')}</p><div class="detail-grid"><div class="detail-item"><span>Базовая цена из API</span><strong>${p.price!=null?money(p.price,p.currency_code||'RUB'):'—'}</strong></div><div class="detail-item"><span>Себестоимость за единицу</span><strong>${cost}</strong></div><div class="detail-item"><span>Остаток, шт.</span><strong>${p.quantity===null?'Неизвестен':n(p.quantity)}</strong></div></div><div class="detail-source">Снимок товаров: ${date(p.importedAt)}<br>${p.market==='Ozon'?'Себестоимость из Ozon · получена '+date(p.costImportedAt)+'. Это текущая величина, а не история закупочных цен.':'Себестоимость WB не сопоставлена с Ozon. Отсутствие остатка в выгрузке не означает ноль.'}</div><p><a class="button" href="/manage.html?product=${encodeURIComponent(p.key)}">Управлять ценой и заметками →</a></p><p>Цены обновлены: ${date(p.pricing?.importedAt)}.</p><h3>Записи остатков</h3><div class="table-wrap"><table><thead><tr><th>Источник / склад</th><th class="numeric">Количество</th></tr></thead><tbody>${p.warehouseRows.map(r=>`<tr><td>${esc(r.warehouse||r.type||'Данные площадки')}</td><td class="numeric">${n(r.present)}</td></tr>`).join('')||'<tr><td colspan="2">Нет строк распределения по складам</td></tr>'}</tbody></table></div>`;$('detail').showModal()}
try{$('hide-inactive').checked=localStorage.getItem('pult-hide-inactive')!=='false'}catch{}
$('hide-inactive').onchange=()=>{try{localStorage.setItem('pult-hide-inactive',String($('hide-inactive').checked))}catch{}page=1;render()};
$('market').onchange=()=>{buildStoreSelect();page=1;render()};$('store').onchange=()=>{page=1;render()};for(const id of ['search','issue','sort'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderTable()});
$('reset').onclick=()=>{$('market').value='';buildStoreSelect();$('store').value='';$('search').value='';$('issue').value='';$('sort').value='name';page=1;render()};
$('attention').onclick=e=>{const b=e.target.closest('[data-issue]');if(!b)return;$('issue').value=b.dataset.issue;$('search').value='';page=1;renderTable();location.hash='products'};
$('prev').onclick=()=>{page--;renderTable()};$('next').onclick=()=>{page++;renderTable()};$('product-rows').onclick=e=>{const b=e.target.closest('[data-product]');if(b)openDetail(b.dataset.product)};$('close-detail').onclick=()=>$('detail').close();
$('export').onclick=()=>{const blob=new Blob([PultModel.csv(filtered)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Пульт-товары-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('store-cards').onclick=async e=>{const b=e.target.closest('[data-sync]');if(!b)return;b.disabled=true;try{await api('/api/sync',{id:b.dataset.sync});await refresh()}catch(error){$('notice').className='error';$('notice').textContent=error.message;b.disabled=false}};
$('refresh-view').onclick=()=>refresh(true);
function nav(){const active=location.hash.slice(1)||'overview';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active))}window.addEventListener('hashchange',nav);nav();void refresh();setInterval(()=>{if(!document.hidden)void refresh()},8000);
